const AI_KEYWORDS = ['ai','gpt','claude','llm','model','agent','automation','chatbot','openai','anthropic','gemini','mistral'];
const items = [];
for (const item of $input.all()) {
  const text = ((item.json.title||'')+(item.json.contentSnippet||'')).toLowerCase();
  const score = AI_KEYWORDS.filter(k => text.includes(k)).length * 12 + 30;
  if (score >= 50) items.push({ json: { ...item.json, relevance_score: Math.min(score, 100) } });
}
return items.sort((a,b) => b.json.relevance_score - a.json.relevance_score).slice(0, 5);

