parameters.functionCode:
const response = JSON.parse($json.body || '{}');
const text = response.content?.[0]?.text || '{}';
try {
  const clean = text.replace(/^```json\n?/, '').replace(/\n?```$/, '');
  const article = JSON.parse(clean);
  const slug = article.title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
  return [{ json: { ...article, slug: slug + '-' + Date.now(), status: 'published', ai_generated: true, author: 'CreatorFlow AI', published_at: new Date().toISOString(), source_url: $('Score et filtrer').item.json.link }}];
} catch { return []; }

const a = $json;
const url = `https://creatorflowmarket.com/blog/${a.slug}`;
return [{
  json: {
    linkedin: `🚀 Nouvel article : ${a.title}\n\n${a.excerpt}\n\n🔗 ${url}\n\n#IA #IntelligenceArtificielle #CreatorFlow`,
    twitter:  `🤖 ${a.title.substring(0,100)}... ${url} #IA`,
    facebook: `📖 ${a.title}\n\n${a.excerpt}\n\n👉 ${url}`,
    article_url: url,
    article_title: a.title
  }
}];
